import{experimentResult}from './eco6-models.js?v=20261023-physicscomplete01';
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const T=(x,y,s,n=17,c='#faf5ed')=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${c}" font-family="sans-serif" font-size="${n}">${E(s)}</text>`;const L=(x,y,u,v,c='#b9d0ca',w=3)=>`<path d="M${x} ${y}L${u} ${v}" stroke="${c}" stroke-width="${w}" fill="none"/>`;const C=(x,y,r=6,c='#efae92')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;const B=(x,y,w,h,c='#365363')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="12" fill="${c}" stroke="#a8c4be"/>`;export const eco6SVG=(a,label)=>`<svg viewBox="0 0 560 440" role="img" aria-label="${E(label)}">${a}</svg>`;
const fish=(x,y,size=1,c='#b9d0ca')=>`<ellipse cx="${x}" cy="${y}" rx="${21*size}" ry="${10*size}" fill="${c}"/><path d="M${x-14*size} ${y}l${-16*size} ${-13*size}v${26*size}z" fill="${c}"/>`+C(x+12*size,y-2*size,2,'#233f4d');
export function farmFigure({a='free',b='cold',revealed=true,progress=1}={}){let r=experimentResult('farming',a,b),vals=[r.movement,r.thermal,r.other,r.value],x=50,body=T(280,30,'Same intake; different energy allocations',22)+T(280,76,a+' movement ·'+b+' surroundings',17)+T(280,112,'100 supplied energy units',19);for(let[i,n]of vals.entries()){let width=n*4.6*progress;body+=`<rect x="${x}" y="145" width="${width}" height="60" fill="${['#aebdcd','#d2b79a','#b5b7b4','#a5c7ad'][i]}"/>`;x+=width;body+=T(280,250+i*34,['Movement','Thermoregulation','Other processes','Retained for growth'][i]+': '+(i===3&&!revealed?'Predict':n),16);}body+=T(280,417,'Original energy units · not animal rates or housing advice',13)+T(280,435,'Output alone does not resolve welfare or environmental trade-offs',12);return eco6SVG(body,`Original farm energy account100: movement ${r.movement}, thermal ${r.thermal}, other30; `+(revealed?'retained '+r.value: 'predict retained energy')+'. Fictional allocations; no universal optimum or ethical ranking.');}
export function fisheriesFigure({a='20',b='large',revealed=true,movie=false,progress=0}={}){let r=experimentResult('fisheries',a,b),body=T(280,30,movie?'Let juveniles escape suitable mesh':'Follow survivors and new recruits',23);if(movie){let x=100+progress*390;body+=B(35,80,490,235,'#2a4d62');for(let y=95;y<300;y+=42)body+=L(320,y,320,y+23,'#b6bda7',4);body+=fish(x,170,.65,'#c2d8bf')+fish(Math.min(280,100+progress*300),245,1.5,'#d8b699')+T(150,340,'Small juvenile',17)+T(410,340,'Larger adult',17)+T(280,385,'Selected size illustration · real gear selectivity varies',15);}else{body+=T(280,70,'Start40 juveniles +60 adults · adult catch '+a,16);for(let[i,[label,n,c]]of[['Juvenile survivors',r.juveniles,'#b7cbb1'],['Adult survivors',r.adults,'#d8b599'],['New recruits',r.recruits,'#b6c6d8']].entries()){let y=115+i*75;body+=T(115,y+23,label,15)+`<rect x="215" y="${y}" width="${n*4}" height="35" fill="${c}"/>`+T(500,y+24,n,18);}body+=T(280,352,b==='small'?'Small mesh:10 extra juvenile bycatch':'Large mesh:0 juvenile bycatch',16)+T(280,388,revealed?'Next model total: '+r.value:'Predict next total',21);}body+=T(280,431,'One fictional cycle · no maturation/immigration/deaths/density effects',12);return eco6SVG(body,movie?'Symbolic suitable mesh lets a smaller juvenile pass while larger adult remains; sizes and speeds not calibrated.':`Fictional stock: adult catch${a},${b} mesh; juvenile survivors${r.juveniles}, adults${r.adults}, recruits${r.recruits}. `+(revealed?'Next total'+r.value: 'Predict next total')+'. Adult target and juvenile bycatch are separate model assumptions, not a legal rule or a long-term forecast.');}
export function vesselFigure({a='20',b='air',revealed=true,progress=0,movie=false}={}){let r=experimentResult('biotechnology',a,b),body=T(280,30,'Fusarium: aerobic food production',23)+`<ellipse cx="225" cy="105" rx="100" ry="30" fill="#8faeb5"/><path d="M125 105V300a100 30 0 0 0 200 0V105" fill="#a5c8cc28" stroke="#b7d1d0" stroke-width="3"/><ellipse cx="225" cy="300" rx="100" ry="30" fill="#436a70"/>`+T(225,95,'Glucose syrup',17)+T(225,260,'Fusarium fungus',17)+T(225,285,'Biomass',16);if(b==='air')for(let i=0;i<7;i++){let y=260-((progress*170+i*23)%160);body+=C(158+i%3*65,y,4,'#bed7dd');}body+=L(225,50,225,78)+L(325,260,395,260)+B(395,210,135,105)+T(462,246,'Harvest',19)+T(462,282,'and purify',17);if(!movie)body+=T(280,353,a+' glucose units · '+(b==='air'?'oxygen supplied':'no supplied oxygen'),17)+T(280,387,revealed?'Aerobic-model output: '+r.value:'Predict aerobic-model output',20);else body+=T(280,367,['Supply glucose and oxygen','Grow fungal biomass aerobically','Harvest biomass','Purify into the food product'][Math.min(3,Math.floor(progress*4))],18);body+=T(280,430,'Original output units · no culture protocol or complete mass balance',12);return eco6SVG(body,`Conceptual Fusarium fungal mycoprotein route: glucose plus oxygen, aerobic growth, harvest and purification. ${a} glucose units, oxygen ${b}. `+(revealed?'Original aerobic-model product'+r.value: 'Predict output')+'. Zero without oxygen is a process assumption, not proof of universal fungal death. Not a calibrated yield or home-culture guide.');}
export function insulinFigure(p=0){let labels=['GM bacterium','Produce insulin','Harvest product','Purify insulin'],body=T(280,32,'A different organism and product',23);for(let[i,s]of labels.entries()){let y=85+i*78;body+=B(85,y,390,55)+T(280,y+35,s,19);if(i<3)body+=L(280,y+55,280,y+78);}body+=C(65,110+p*240,7)+T(280,426,'Conceptual production route · not medical preparation instructions',13);return eco6SVG(body,'Genetically modified bacterium produces human insulin; product harvested and purified for use in diabetes treatment. Distinct from fungal mycoprotein. Conceptual route, not clinical or home-production instructions.');}
const evidence={farming:['Growth output is only one criterion','Protein-rich feed supports protein synthesis','Compare welfare, inputs, cost and environmental effects'],fisheries:['Mesh: size selectivity · quota: catch limit','Retain breeding populations and monitor stocks','Local disappearance is not necessarily global extinction'],biotechnology:['Fusarium fungus → mycoprotein food','GM bacterium → purified human insulin','GM crops: trait-specific yield or nutritional benefits']};
export function productionFigure(o={}){if(o.concealed)return eco6SVG(T(280,220,'Predict, then reveal the evidence',22),'Evidence concealed until prediction');let k=o.kind||'farming',base=k.replace(/-(model|data)$/,'');if(k==='farming-model')return farmFigure(o);if(k==='fisheries-model')return fisheriesFigure(o);if(k==='biotechnology-model')return vesselFigure(o);if(k==='insulin')return insulinFigure(o.progress??0);let rows=evidence[base]||evidence.farming;return eco6SVG(T(280,35,'Connect the method, benefit and limitation',22)+rows.map((s,i)=>T(280,135+i*88,s,16)).join('')+T(280,430,'Original teaching comparison · use the supplied context',13),rows.join('. '));}
